import java.util.*;

class Solution {
  public TreeNode balanceBST(TreeNode root) {
    List<Integer> values = new ArrayList<>();
    inorder(root, values);
    return build(values, 0, values.size() - 1);
  }

  private void inorder(TreeNode node, List<Integer> values) {
    if (node == null) return;
    inorder(node.left, values);
    values.add(node.val);
    inorder(node.right, values);
  }

  private TreeNode build(List<Integer> values, int left, int right) {
    if (left > right) return null;
    int middle = left + (right - left) / 2;
    TreeNode node = new TreeNode(values.get(middle));
    node.left = build(values, left, middle - 1);
    node.right = build(values, middle + 1, right);
    return node;
  }
}
